// Sesquipedalian service worker – generated by scripts/build-words.js from
// scripts/sw.template.js. Do not edit sw.js; edit the template.
//
// - The app shell is precached on install, per version, and served cache-first.
// - A new version installs alongside and WAITS: the page shows a 'New version
//   available' bar (front card and scoreboard only) and tapping it sends
//   SKIP_WAITING. Nothing is swapped silently.
// - Stills (assets/stills/) are cached on first use, cache-first, keeping the
//   most recently used 60. A still that isn't cached and can't be fetched is
//   a network error; the page falls back to the placeholder.
// - Paths are relative to the worker's scope (the project folder), never the
//   site root, so it works under /moirawordgame/ on GitHub Pages.

'use strict';

const VERSION = {"commit":"2dc336d","dirty":true,"builtAt":"2026-11-15T20:49:32.141Z"};
const SHELL = [
  "index.html",
  "style.css",
  "version.js",
  "words.js",
  "storage.js",
  "pwa.js",
  "game.js",
  "manifest.webmanifest",
  "assets/fonts/josefin-sans-latin.woff2",
  "assets/fonts/josefin-sans-latin-ext.woff2",
  "assets/placeholder.svg",
  "assets/icons/apple-touch-icon.png",
  "assets/icons/favicon.ico",
  "assets/icons/favicon-32.png",
  "assets/icons/icon-192.png",
  "assets/icons/icon-512.png",
  "assets/icons/icon-512-maskable.png"
];

const SHELL_CACHE = `sesquipedalian-shell-${VERSION.commit}-${VERSION.builtAt}`;
const STILLS_CACHE = 'sesquipedalian-stills';   // kept across versions
const STILLS_LIMIT = 60;

const scoped = path => new URL(path, self.registration.scope).href;

self.addEventListener('install', event => {
  // Fetch every shell file fresh from the network (not the HTTP cache), so the
  // new version is really the new version.
  event.waitUntil(caches.open(SHELL_CACHE).then(cache =>
    cache.addAll(SHELL.map(path => new Request(scoped(path), { cache: 'reload' })))));
  // No skipWaiting() here: the page asks for it when the player taps the bar.
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('sesquipedalian-shell-') && key !== SHELL_CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  const msg = event.data || {};
  if (msg.type === 'SKIP_WAITING') self.skipWaiting();
  if (msg.type === 'GET_VERSION' && event.ports[0]) event.ports[0].postMessage(VERSION);
});

// Keep only the `limit` most recently used entries (cache.keys() lists the
// oldest first; a hit re-adds the entry, moving it to the end).
async function trimCache(cache, limit) {
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - limit; i++) await cache.delete(keys[i]);
}

async function still(event) {
  const cache = await caches.open(STILLS_CACHE);
  const hit = await cache.match(event.request);
  if (hit) {
    // Mark as recently used.
    event.waitUntil(cache.delete(event.request).then(() => cache.put(event.request, hit.clone())));
    return hit;
  }
  let response;
  try {
    response = await fetch(event.request);
  } catch (e) {
    return Response.error();               // offline and not cached: the page shows the placeholder
  }
  if (response.ok) {
    event.waitUntil(cache.put(event.request, response.clone()).then(() => trimCache(cache, STILLS_LIMIT)));
  }
  return response;
}

async function shellOrNetwork(event) {
  const cache = await caches.open(SHELL_CACHE);
  const hit = await cache.match(event.request, { ignoreSearch: true });
  if (hit) return hit;
  try {
    return await fetch(event.request);
  } catch (e) {
    return Response.error();
  }
}

// Navigations: the game is one page. The scope itself (or index.html) gets
// the cached shell; any other path in scope (a stale deep link) is sent to the
// scope, so the page's relative paths resolve.
async function navigate(event) {
  const url = new URL(event.request.url);
  const scope = new URL(self.registration.scope);
  if (url.pathname !== scope.pathname && url.pathname !== scope.pathname + 'index.html') {
    return Response.redirect(scope.href, 302);
  }
  const cache = await caches.open(SHELL_CACHE);
  const hit = await cache.match(scoped('index.html'));
  if (hit) return hit;
  try { return await fetch(event.request); } catch (e) { return Response.error(); }
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || !url.href.startsWith(self.registration.scope)) return;
  if (request.mode === 'navigate') return event.respondWith(navigate(event));
  if (url.pathname.includes('/assets/stills/')) return event.respondWith(still(event));
  event.respondWith(shellOrNetwork(event));
});
